pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address tokenOwner, address recipient, uint256 amount) public {
        vm.assume(tokenOwner != address(0));
        vm.assume(recipient != address(0));
        vm.assume(tokenOwner != address(c));
        vm.assume(recipient != address(c));
        Token t = new Token();
        address[] memory tos = new address[](1);
        uint256[] memory vs = new uint256[](1);
        tos[0] = recipient;
        vs[0] = bound(amount, 1, type(uint256).max / 2);
        vm.prank(tokenOwner);
        bool ok = c.transfer(address(t), tos, vs);
        assertTrue(ok);
    }
}

contract Token {
    mapping(address => uint256) public balances;
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }
}
